<style>
#store-profile-feedback{scroll-margin-top:120px;margin-top:16px}
.store-profile-page{max-width:1120px;margin:0 auto;color:#173f35;font-size:13px;min-width:0}.store-profile-page [hidden]{display:none!important}.stp-nav{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:20px}.stp-nav a{display:inline-flex;align-items:center;min-height:40px;padding:9px 15px;border:1px solid #dce6df;border-radius:10px;background:#fff;color:#52665d;font-size:12px;font-weight:500;transition:background .15s}.stp-nav a:hover{background:#edf5f0;color:#173f35}.stp-nav .stp-security{margin-left:auto;background:transparent;border-color:transparent}.stp-card{background:#fff;border:1px solid #dde6e1;border-radius:18px;padding:24px 28px;margin-bottom:20px;box-shadow:0 6px 24px #173f3505;scroll-margin-top:112px;min-width:0}.stp-section-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;margin-bottom:22px}.stp-section-heading h2{font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:#1f6f5b;margin:0}.stp-section-heading p{font-size:12px;line-height:1.6;color:#71817b;margin:5px 0 0}.stp-badge{display:inline-flex;align-items:center;padding:5px 10px;border-radius:20px;font-size:11px;font-weight:600;background:#eaf6ef;color:#1f6f5b;white-space:nowrap}.stp-pending{background:#fff6e1;color:#95610e}.stp-readonly{display:grid;grid-template-columns:minmax(0,.65fr) minmax(0,1.35fr);gap:16px;padding:16px 18px;background:#f5f8f6;border:1px solid #e4ebe6;border-radius:12px;margin:0 0 22px}.stp-readonly dt,.stp-business-grid dt{color:#71817b;font-size:11px;margin-bottom:6px}.stp-readonly dd,.stp-business-grid dd{font-weight:500;overflow-wrap:anywhere;margin:0}.stp-field{margin:0 0 18px;min-width:0}.store-profile-page label{display:block;font-size:12px;font-weight:500;margin-bottom:7px}.store-profile-page :is(input:not([type=hidden]):not([type=file]),textarea,select){display:block;width:100%;min-width:0;max-width:100%;box-sizing:border-box;padding:11px 13px;border:1px solid #d5e1d9;border-radius:9px;background:#fff;color:#173f35;font:inherit;font-size:13px;min-height:43px;box-shadow:0 2px 4px #173f3502}.store-profile-page input[readonly]{background:#f5f8f6;color:#63766c;box-shadow:none}.store-profile-page select:disabled{background:#f5f8f6;color:#71817b}.store-profile-page textarea{resize:vertical;line-height:1.7;min-height:100px}.store-profile-page input::placeholder,.store-profile-page textarea::placeholder{color:#8b9992}.stp-hint{font-size:11px;font-weight:400;line-height:1.6;color:#71817b;margin:6px 0 0}.stp-required{color:#b45040}.stp-label-row{display:flex;align-items:center;justify-content:space-between;gap:12px}.stp-label-row>span{margin:0 0 7px}.stp-logo-row{display:flex;align-items:center;gap:20px;margin:22px 0}.stp-logo-preview{width:100px;height:100px;flex-shrink:0;border-radius:18px;overflow:hidden;background:#f2f7f4;border:1px solid #dce6df}.stp-logo-preview img{width:100%;height:100%;object-fit:cover;display:block}.stp-logo-preview>span{display:grid;place-items:center;width:100%;height:100%;color:#1f6f5b}.stp-logo-preview :is(svg,i){width:30px;height:30px}.stp-image-controls{min-width:0;flex:1}.stp-image-controls>label{margin-bottom:0;font-weight:600}.store-profile-page input[type=file]{display:block;width:100%;max-width:100%;min-width:0;box-sizing:border-box;font:inherit;font-size:11px;color:#71817b;margin-top:10px}.store-profile-page input[type=file]::file-selector-button{min-height:38px;padding:8px 12px;margin-right:10px;border:1px solid #d5e1d9;background:#fff;border-radius:9px;font:inherit;font-weight:500;color:#1f6f5b;cursor:pointer}.stp-image-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:6px}.store-profile-page button[data-clear-image],.stp-danger{padding:7px 10px;min-height:36px;border:0;background:transparent;font:inherit;font-size:11px;font-weight:500;color:#1f6f5b;cursor:pointer;border-radius:8px}.store-profile-page .stp-danger{color:#ac4a3b}.stp-banner-editor{padding-top:20px;border-top:1px solid #edf1ee;margin-bottom:22px}.stp-banner-preview{display:grid;place-items:center;width:100%;aspect-ratio:6/1;max-height:170px;min-height:85px;background:#f2f7f4;border:1px dashed #d4e1d8;border-radius:12px;overflow:hidden;color:#71817b;font-size:12px}.stp-banner-preview img{width:100%;height:100%;min-height:0;object-fit:cover;display:block}.stp-banner-controls{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.stp-banner-controls input{flex:1;min-width:150px}.stp-form-footer{display:flex;justify-content:space-between;align-items:center;gap:16px;padding-top:18px;border-top:1px solid #edf1ee}.stp-form-footer .stp-hint{margin:0}.stp-primary{display:inline-flex;justify-content:center;align-items:center;min-height:43px;padding:11px 18px;border:1px solid #173f35;border-radius:9px;background:#173f35;color:white;font:inherit;font-size:12px;font-weight:600;cursor:pointer;white-space:nowrap}.stp-primary:hover{background:#215848}.stp-primary:disabled{opacity:.6;cursor:wait}.stp-grid,.stp-business-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:20px}.stp-address-summary{padding:14px 16px;background:#f5f8f6;border:1px solid #e4ebe6;border-radius:11px;margin-bottom:22px}.stp-address-summary>span{display:block;font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:#71817b}.stp-address-summary p{font-size:12px;line-height:1.7;margin:6px 0 0;overflow-wrap:anywhere}.stp-business-grid{row-gap:22px;margin:0}.stp-business-note{font-size:11px;line-height:1.7;padding:13px 16px;background:#f5f8f6;border-radius:10px;margin:22px 0 0;color:#71817b}.stp-business-note a{color:#1f6f5b;font-weight:600;text-decoration:underline}.stp-readonly-label{font-size:10px;color:#71817b;border:1px solid #e4ebe6;border-radius:20px;padding:4px 9px;white-space:nowrap}.stp-feedback{padding:14px 18px;border-radius:12px;margin-bottom:18px;font-size:12px;line-height:1.7}.stp-success{color:#1f6f5b;border:1px solid #bcdfca;background:#edf9f2}.stp-errors{color:#a14034;border:1px solid #efcfc9;background:#fff5f3}.stp-errors ul{list-style:disc;padding-left:18px;margin-top:5px}.stp-field-error{color:#a14034;font-size:11px;margin:6px 0 0;line-height:1.6}.store-profile-page :is(button,a,input,select,textarea):focus-visible{outline:3px solid #7daf98;outline-offset:3px}.store-profile-page [aria-invalid=true]{border-color:#c56f60!important}
@media(max-width:640px){.stp-card{padding:20px 18px;border-radius:14px}.stp-nav{gap:6px}.stp-nav a{font-size:11px;padding:9px 11px}.stp-nav .stp-security{margin-left:0}.stp-grid,.stp-business-grid,.stp-readonly{grid-template-columns:minmax(0,1fr)}.stp-readonly{gap:14px}.stp-logo-row{align-items:flex-start;gap:14px}.stp-logo-preview{width:76px;height:76px;border-radius:14px}.stp-form-footer{align-items:stretch;flex-direction:column;gap:12px}.stp-form-footer .stp-primary{width:100%}.stp-banner-preview{aspect-ratio:4/1}.stp-business-grid{gap:18px}.stp-section-heading{margin-bottom:18px}}
</style>
